<script setup>
import {wbPublishStatus,wbPublishPhase} from '../../../../src/shared/wb-publish-status.js';
import {useRouter} from 'vue-router';
import {onBeforeUnmount} from 'vue';
import {wbHasSizeFields,wbNativeSize,wbNativePrice} from '../../../../src/shared/wb-native-fields.js';
import {generateAiVideo} from '../../api/tools/aiImageGenerator.js';
import {uploadListingMedia} from '../../api/tools/imageCropper';
import {wbAttributeLabel} from '../../../../src/shared/wb-display.js';
import {computed,nextTick,reactive,ref} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {apiClient,currentApiCacheScope} from '../../utils/api.js';
import WbBrandInput from './WbBrandInput.vue';
import WbPublishMediaSummary from './WbPublishMediaSummary.vue';
import WbAttributeInput from './WbAttributeInput.vue';
import WbListingVariantEditor from './WbListingVariantEditor.vue';
import {wbListingVariants,wbNewVariant,wbGeneratedVendorCode} from '../../../../src/shared/wb-listing-variants.js';
const props=defineProps({shopId:{type:Number,default:null},shops:{type:Array,default:()=>[]},schema:{type:Object,required:true},templates:{type:Array,default:()=>[]},draft:{type:Object,default:null},card:{type:Object,default:null}}),emit=defineEmits(['saved','shop-changed','upload-state']);
const clone=v=>JSON.parse(JSON.stringify(v)),initial=props.draft?.payload||{card:props.card||{title:'',vendorCode:'',brand:'',description:'',dimensions:{length:null,width:null,height:null,weightBrutto:null},characteristics:clone(props.schema.defaults?.characteristics||[]),sizes:[{techSize:'0',price:null,skus:[]}]},images:(props.card?.photos||[]).map(p=>p.big).filter(Boolean)};
function nativeRow(row){const value=clone(row);value.card.sizes=value.card.sizes.map(wbNativeSize);return value;}
const rows=ref(wbListingVariants(initial).map(nativeRow)),shop=ref(props.draft?.target_shop_id||props.draft?.shop_id||props.shopId||null),savedShop=ref(props.draft?.shop_id||props.shopId||null),draftId=ref(props.draft?.id||null),revision=ref(props.draft?.revision||1),strategy=ref(initial.strategy||'grouped'),busy=ref(false),uploading=ref(0),active=ref(null),details=ref(null),preview=ref(false),errors=ref([]),source=reactive({query:'',rows:[]});
const router=useRouter(),publication=reactive({review:null,job:null,loading:false});let publishTimer;
const selectedRows=ref([]),variantTable=ref(null);
const attributes=computed(()=>props.schema.attributes.filter(a=>!a.existNamedField&&Number(a.charcType)!==0).sort((a,b)=>Number(Boolean(b.required))-Number(Boolean(a.required))||Number(Boolean(b.isVariable))-Number(Boolean(a.isVariable))));
const editorMode=ref('images'),dialogTitle=computed(()=>'编辑商品图片');
const hasSizeFields=computed(()=>wbHasSizeFields(props.schema.attributes,rows.value));
const pricing=reactive({visible:false,multiplier:Number(initial.price_strategy?.multiplier)||1,bases:[]});
const pricePreview=computed(()=>pricing.bases.map(item=>{try{return {...item,price:wbNativePrice(item.base_price,pricing.multiplier)};}catch(e){return {...item,error:e.message};}}));
function openPricing(){pricing.bases=rows.value.flatMap((row,rowIndex)=>row.card.sizes.map((size,sizeIndex)=>({rowIndex,sizeIndex,base_price:size.price})));pricing.visible=!pricing.visible;}
function applyPricing(){if(pricePreview.value.some(item=>item.error))return ElMessage.warning('请补全已有价格和倍率。');for(const item of pricePreview.value)rows.value[item.rowIndex].card.sizes[item.sizeIndex].price=item.price;pricing.visible=false;}
function addSize(row){if(row.card.sizes.length<30)row.card.sizes.push({price:row.card.sizes[0]?.price??null,skus:[],...(hasSizeFields.value?{techSize:'',wbSize:''}:{})});}
function setBarcodes(size,text){size.skus=String(text).split(/[,，\s]+/).filter(Boolean);}
let videoQueue=Promise.resolve();
function uploadVideo(row,options){const scope=currentApiCacheScope();uploadingChanged(uploading.value+1);const task=videoQueue.catch(()=>{}).then(async()=>{try{if(scope!==currentApiCacheScope())throw Error('账户已切换，请重新上传。');if(options.file.size>50*1024*1024||!/\.(mp4|mov)$/i.test(options.file.name))throw Error('视频请使用不超过 50MB 的 MP4 或 MOV 文件。');const result=await uploadListingMedia(options.file,{source_module:'wb_listing',role:'listing_video'});if(scope!==currentApiCacheScope())return;if(result.mediaType!=='video'||!result.publishUrl)throw Error('视频未生成可用地址，请重试。');row.video_url=result.publishUrl;row.video_source_image='';options.onSuccess?.(result);}catch(e){options.onError?.(e);if(scope===currentApiCacheScope())ElMessage.error(e.message);}finally{uploadingChanged(uploading.value-1);}});videoQueue=task;return task;}
function flush(){if(active.value!==null&&details.value)rows.value[active.value]=details.value.getPayload();}
function payload(){flush();const variants=clone(rows.value);for(const row of variants)row.card.sizes=row.card.sizes.map(wbNativeSize);return {...clone(initial),currency:'CNY',strategy:strategy.value,price_strategy:{mode:'native_price',multiplier:pricing.multiplier},template_id:Number(props.schema.template_id),subject_id:Number(props.schema.subject_id),variants,card:variants[0]?.card||{},images:variants[0]?.images||[],video_url:variants[0]?.video_url||''};}
function generate(row,index){if(row.card.nmID||draftId.value&&index===0)return;row.card.vendorCode=wbGeneratedVendorCode({brand:row.card.brand,subjectId:props.schema.subject_id,shopId:shop.value,index,random:crypto.randomUUID().replaceAll('-','').slice(0,10).toUpperCase()});}
function generateAll(){rows.value.forEach((row,index)=>{if(!row.card.vendorCode)generate(row,index);});}
function addVariant(){if(rows.value.length>=30)return;const row=wbNewVariant(rows.value[0]);row.card.characteristics=clone((rows.value[0].card.characteristics||[]).filter(c=>props.schema.attributes.find(a=>Number(a.charcID)===Number(c.id))?.isVariable!==true));generate(row,rows.value.length);rows.value.push(row);}
async function edit(index,mode='images'){if(uploading.value)return;flush();active.value=null;editorMode.value=mode;await nextTick();active.value=index;}
function closeDetails(done){if(uploading.value)return;flush();active.value=null;if(typeof done==='function')done();}
function sameFirst(key){for(const row of rows.value.slice(1))row.card[key]=clone(rows.value[0].card[key]);}
function sameDimension(key){for(const row of rows.value.slice(1))row.card.dimensions[key]=rows.value[0].card.dimensions[key];}
function copyImages(){for(const row of rows.value.slice(1))row.images=clone(rows.value[0].images);}
function copyVideos(){for(const row of rows.value.slice(1)){row.video_url=rows.value[0].video_url||'';row.video_source_image=rows.value[0].video_source_image||'';}}
function copyPrices(){for(const row of rows.value.slice(1))for(const size of row.card.sizes)size.price=rows.value[0].card.sizes[0].price;}
async function generateVideo(index){const row=rows.value[index];if(uploading.value||busy.value||!row.images[0])return;await run(async scope=>{const image=row.images[0];uploadingChanged(uploading.value+1);try{const result=await generateAiVideo({imageUrl:image,sourceId:row.card.vendorCode,title:row.card.title},{sourceModule:'wb_listing_video',listingVariantMedia:true});if(scope!==currentApiCacheScope())return;const url=result.video?.publishUrl||result.video?.publish_url;if(!url)throw Error('视频未生成可用地址，请查看任务记录。');row.video_url=url;row.video_source_image=image;}finally{uploadingChanged(uploading.value-1);}});}
function removeSelected(){const selected=new Set(selectedRows.value);rows.value=rows.value.filter((row,index)=>index===0||!selected.has(row));selectedRows.value=[];variantTable.value?.clearSelection();}
function remove(index){if(rows.value.length===1||draftId.value&&index===0)return;rows.value.splice(index,1);}
async function run(work){if(busy.value||uploading.value)return;busy.value=true;const scope=currentApiCacheScope();try{await work(scope);}catch(e){if(scope===currentApiCacheScope())ElMessage.error(e.message);}finally{busy.value=false;}}
async function findSource(){await run(async scope=>{const r=await apiClient.get(`/api/listing/drafts?paged=1&lightweight=1&pageSize=20&query=${encodeURIComponent(source.query)}`,{noCache:true});if(scope===currentApiCacheScope())source.rows=r.rows||[];});}
async function importSource(id){await run(async scope=>{const r=await apiClient.get(`/api/wb/listing-source?source_draft_id=${id}${shop.value?`&shop_id=${shop.value}`:''}`,{noCache:true});if(scope!==currentApiCacheScope())return;rows.value=wbListingVariants(r).map(nativeRow);source.rows=[];generateAll();});}
async function save(){if(!shop.value)throw Error('上架店铺：请在顶部选择目标 WB 店铺，再保存草稿。');generateAll();let saveId=draftId.value;if(saveId&&Number(savedShop.value)!==Number(shop.value)){await ElMessageBox.confirm('将保存为目标店铺的新草稿，原店铺草稿保留。','保存新店铺草稿');saveId=null;}const r=await apiClient.post('/api/wb/listing-drafts/save',{shop_id:shop.value,draft_id:saveId,revision:revision.value,payload:payload()});draftId.value=r.draft_id;revision.value=r.revision;savedShop.value=shop.value;emit('saved');}
async function saveOnly(){await run(async()=>{await save();ElMessage.success('WB 草稿已保存，未提交上架');});}
async function validate(){preview.value=true;errors.value=[];publication.review=null;await run(async scope=>{const r=await apiClient.post('/api/wb/listing-preview',{shop_id:shop.value,payload:payload()});if(scope===currentApiCacheScope())errors.value=r.errors||[];});}
async function generateBarcodes(sizes=null){await run(async scope=>{if(!shop.value)throw Error('请先选择 WB 店铺。');const missing=(sizes||rows.value.flatMap(row=>row.card.sizes)).filter(size=>!size.skus?.length);if(!missing.length)return ElMessage.info('当前各规格已有条码。');const r=await apiClient.post('/api/wb/listing-barcodes',{shop_id:shop.value,count:missing.length});if(scope!==currentApiCacheScope())return;missing.forEach((size,index)=>{size.skus=[r.barcodes[index]];});publication.review=null;errors.value=[];ElMessage.success('已从 WB 获取条码，请保存草稿。');});}
async function reviewSubmission(){preview.value=true;errors.value=[];publication.review=null;publication.job=null;await run(async scope=>{await save();if(scope!==currentApiCacheScope())return;const r=await apiClient.post('/api/wb/listing-publish/review',{shop_id:shop.value,draft_id:draftId.value});if(scope!==currentApiCacheScope())return;errors.value=r.errors||[];publication.review=r;});}
async function pollPublication(){if(!publication.job?.id)return;const scope=currentApiCacheScope();try{const r=await apiClient.get(`/api/wb/publish-job?job_id=${publication.job.id}`,{noCache:true});if(scope!==currentApiCacheScope())return;publication.job=r.job;if(['queued','processing'].includes(r.job.status))publishTimer=setTimeout(pollPublication,10000);}catch(e){if(scope===currentApiCacheScope())ElMessage.error('发布记录暂时未刷新，请到上架记录核对结果。');}}
async function confirmSubmission(){await run(async scope=>{const r=publication.review;if(!r?.ok||!r.review_hash)throw Error('请先重新预览并核对商品资料。');const job=await apiClient.post('/api/wb/listing-publish/submit',{shop_id:r.shop_id,draft_id:r.draft_id,revision:r.revision,review_hash:r.review_hash,confirmed:true});if(scope!==currentApiCacheScope())return;publication.job=job.job;publication.review=null;ElMessage.success('发布任务已创建，请等待平台处理结果。');emit('saved');await pollPublication();});}
onBeforeUnmount(()=>clearTimeout(publishTimer));
function uploadingChanged(value){uploading.value=value;emit('upload-state',value);}
function attributeValue(row,attribute){return row.card.characteristics?.find(v=>Number(v.id)===Number(attribute.charcID))?.value;}
function updateAttribute(row,attribute,value){row.card.characteristics=(row.card.characteristics||[]).filter(v=>Number(v.id)!==Number(attribute.charcID));row.card.characteristics.push({id:attribute.charcID,value:Number(attribute.charcType)===4?value:Array.isArray(value)?value:String(value||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean)});}
function sameAttribute(attribute){const value=attributeValue(rows.value[0],attribute);for(const row of rows.value.slice(1))updateAttribute(row,attribute,value===undefined?'':clone(value));}
defineExpose({getPayload:payload,getShopId:()=>shop.value,getContext:()=>({id:draftId.value,revision:revision.value,shop_id:savedShop.value,target_shop_id:shop.value,payload:payload()}),saveDraft:saveOnly,preview:validate,reviewSubmission});
</script>
<template>
 <div class="wb-workbench-fields">
  <section class="editor-block primary-information"><h3>主要信息</h3><el-form label-width="116px" class="workbench-settings" :disabled="busy||uploading>0"><el-form-item label="上架店铺" required><el-select v-model="shop" placeholder="选择 WB 店铺" clearable @change="id=>{if(id&&shops.find(s=>Number(s.id)===Number(id))?.environment!==schema.environment)emit('shop-changed');}"><el-option v-for="s in shops" :key="s.id" :value="Number(s.id)" :label="s.name"/></el-select></el-form-item><el-form-item label="商品组合"><div class="product-grouping"><el-radio-group v-model="strategy"><el-radio value="grouped">合并为一个商品</el-radio><el-radio value="independent">分别作为独立商品</el-radio></el-radio-group><p class="grouping-help">{{strategy==='grouped'?'例如：同款的不同颜色，作为一个商品的多个变体。':'每行分别建立商品，各自保留图片、属性和尺码。'}}</p></div></el-form-item><el-form-item label="产品类目" required><slot name="category"/></el-form-item></el-form></section>
  <section v-if="!draftId" class="editor-block source-bar"><el-input v-model="source.query" placeholder="引用已有草稿：输入货号或名称" @keyup.enter="findSource"/><el-button :loading="busy" @click="findSource">搜索草稿</el-button><el-table v-if="source.rows.length" :data="source.rows"><el-table-column prop="internal_code" label="货号"/><el-table-column prop="product_name" label="商品"/><el-table-column width="80"><template #default="{row}"><el-button link @click="importSource(row.id)">引用</el-button></template></el-table-column></el-table></section>
  <section class="editor-block variants-block"><div class="section-line"><h3>WB 商品表格</h3><div class="variant-actions"><el-button type="primary" :disabled="rows.length>=30||busy||uploading>0" @click="addVariant">＋ 添加变体</el-button><el-button :disabled="busy||uploading>0" @click="generateAll">一键生成货号</el-button><el-button :disabled="busy||uploading>0" @click="openPricing()">定价策略</el-button><el-button :disabled="busy||uploading>0||!shop" @click="generateBarcodes()">生成缺失条码</el-button><el-dropdown trigger="click" :disabled="busy||uploading>0"><el-button>批量操作</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="copyImages">图片同首行</el-dropdown-item><el-dropdown-item @click="copyVideos">视频同首行</el-dropdown-item><el-dropdown-item @click="sameFirst('title')">标题同首行</el-dropdown-item><el-dropdown-item @click="sameFirst('description')">描述同首行</el-dropdown-item><el-dropdown-item @click="copyPrices">售价同首行</el-dropdown-item><el-dropdown-item divided :disabled="!selectedRows.length" @click="removeSelected">删除选中变体（保留首行）</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></div>
  <section v-if="pricing.visible" class="inline-pricing"><div class="media-cell-actions"><strong>价格倍率</strong><el-input-number v-model="pricing.multiplier" :min="0.01" :precision="2"/><span>以当前已有价格为基数；仅修改草稿</span><el-button type="primary" @click="applyPricing">应用倍率</el-button><el-button @click="pricing.visible=false">收起</el-button></div><el-table :data="pricePreview" border><el-table-column prop="base_price" label="已有价格"/><el-table-column prop="price" label="倍率后价格"/><el-table-column prop="error" label="需补充内容"/></el-table></section>
   <el-table ref="variantTable" :data="rows" :max-height="640" border stripe class="variant-table dense-variant-table" :scrollbar-always-on="true" @selection-change="selectedRows=$event">
    <el-table-column type="selection" width="46" fixed="left"/>
    <el-table-column type="index" label="序号" width="64" fixed="left" align="center"/>
    <el-table-column label="商品信息" fixed="left">
     <el-table-column width="210" fixed="left"><template #header><div class="variant-col-header"><span><em>*</em> 货号 / vendorCode</span><el-button link size="small" @click="generateAll">一键生成</el-button></div></template><template #default="{row,$index}"><div class="offer-id-cell"><el-input v-model="row.card.vendorCode" size="small" :disabled="!!row.card.nmID||!!draftId&&$index===0" maxlength="72"/><el-button size="small" :disabled="!!row.card.nmID||!!draftId&&$index===0" @click="generate(row,$index)">生成</el-button></div></template></el-table-column>
     <el-table-column width="260"><template #header><div class="variant-col-header"><span><em>*</em> SKU 名称 / 标题</span><el-button link size="small" @click="sameFirst('title')">同首行</el-button></div></template><template #default="{row}"><el-input v-model="row.card.title" type="textarea" :rows="3" maxlength="60" show-word-limit/></template></el-table-column>
     <el-table-column width="150"><template #header><div class="variant-col-header"><span>品牌</span><el-button link size="small" @click="sameFirst('brand')">同首行</el-button></div></template><template #default="{row}"><WbBrandInput v-model="row.card.brand" :subject-id="Number(schema.subject_id)" :shop-id="shop"/></template></el-table-column>
    </el-table-column>
    <el-table-column label="媒体">
     <el-table-column width="150"><template #header><div class="variant-col-header"><span><em>*</em> 图片</span><el-button link size="small" @click="copyImages">同首行</el-button></div></template><template #default="{row,$index}"><el-image v-if="row.images.length" :src="row.images[0]" :preview-src-list="row.images" preview-teleported fit="cover" class="row-image"/><div v-else class="row-image empty-image">无图</div><el-button link type="primary" @click="edit($index)">编辑图片（{{row.images.length}}）</el-button></template></el-table-column>
     <el-table-column width="190"><template #header><div class="variant-col-header"><span>视频</span><el-button link size="small" @click="copyVideos">同首行</el-button></div></template><template #default="{row,$index}"><video v-if="row.video_url" :src="row.video_url" controls preload="none" class="row-video"/><div v-else class="empty-video">暂无视频</div><div class="media-cell-actions"><el-button link type="primary" :disabled="!row.images.length||uploading>0" @click="generateVideo($index)">一键生成</el-button><el-upload :show-file-list="false" :http-request="options=>uploadVideo(row,options)" accept=".mp4,.mov" :disabled="busy||uploading>0"><el-button link type="primary" :disabled="busy||uploading>0">上传视频</el-button></el-upload></div><el-input v-model="row.video_url" placeholder="HTTPS 视频地址" clearable/></template></el-table-column>
    </el-table-column>
    <el-table-column label="规格与价格">
     <el-table-column label="条码与规格" :width="hasSizeFields?340:230"><template #default="{row}"><div v-for="(size,index) in row.card.sizes" :key="size.chrtID||index" class="inline-size"><template v-if="hasSizeFields"><el-input v-model="size.techSize" placeholder="商品尺码"/><el-input v-model="size.wbSize" placeholder="WB 尺码（适用时填写）"/></template><el-input :model-value="(size.skus||[]).join('\n')" type="textarea" :rows="2" placeholder="商品条码，每行一个" @update:model-value="setBarcodes(size,$event)"/><el-button v-if="!size.skus?.length" link type="primary" :disabled="busy||uploading>0||!shop" @click="generateBarcodes([size])">生成条码</el-button><el-button v-if="row.card.sizes.length>1" link type="danger" @click="row.card.sizes.splice(index,1)">删除该规格</el-button></div><el-button v-if="hasSizeFields" link :disabled="row.card.sizes.length>=30" @click="addSize(row)">添加尺码</el-button></template></el-table-column>
     <el-table-column width="190"><template #header><div class="variant-col-header"><span>价格（CNY）</span><el-button link size="small" @click="copyPrices">同首行</el-button></div></template><template #default="{row}"><div v-for="(size,index) in row.card.sizes" :key="size.chrtID||index" class="inline-size"><small v-if="row.card.sizes.length>1">{{size.techSize||'规格 '+(index+1)}}</small><el-input-number v-model="size.price" :min="1" :precision="0" :controls="false"/></div></template></el-table-column>
    </el-table-column>
    <el-table-column label="包装"><el-table-column width="165"><template #header><div class="variant-col-header"><span>包装长（cm）</span><el-button link size="small" @click="sameDimension('length')">同首行</el-button></div></template><template #default="{row}"><el-input-number v-model="row.card.dimensions.length" :precision="0" :min="1" :controls="false"/></template></el-table-column><el-table-column width="165"><template #header><div class="variant-col-header"><span>包装宽（cm）</span><el-button link size="small" @click="sameDimension('width')">同首行</el-button></div></template><template #default="{row}"><el-input-number v-model="row.card.dimensions.width" :precision="0" :min="1" :controls="false"/></template></el-table-column><el-table-column width="165"><template #header><div class="variant-col-header"><span>包装高（cm）</span><el-button link size="small" @click="sameDimension('height')">同首行</el-button></div></template><template #default="{row}"><el-input-number v-model="row.card.dimensions.height" :precision="0" :min="1" :controls="false"/></template></el-table-column><el-table-column width="165"><template #header><div class="variant-col-header"><span>包装重量（kg）</span><el-button link size="small" @click="sameDimension('weightBrutto')">同首行</el-button></div></template><template #default="{row}"><el-input-number v-model="row.card.dimensions.weightBrutto" :precision="3" :min="0.001" :controls="false"/></template></el-table-column></el-table-column>
    <el-table-column label="内容"><el-table-column width="280"><template #header><div class="variant-col-header"><span>简介 / 描述</span><el-button link size="small" @click="sameFirst('description')">同首行</el-button></div></template><template #default="{row}"><el-input v-model="row.card.description" type="textarea" :rows="3"/></template></el-table-column></el-table-column>
    <el-table-column v-for="attribute in attributes" :key="attribute.charcID" width="210"><template #header><div class="variant-col-header"><span><em v-if="attribute.required">*</em> {{wbAttributeLabel(attribute)}}</span><el-button link size="small" @click="sameAttribute(attribute)">同首行</el-button></div></template><template #default="{row}"><WbAttributeInput :model-value="attributeValue(row,attribute)" :attribute="attribute" :subject-id="Number(schema.subject_id)" :shop-id="shop" @update:model-value="updateAttribute(row,attribute,$event)"/></template></el-table-column>
    <el-table-column label="操作" width="110" fixed="right"><template #default="{$index}"><el-button link type="danger" :disabled="rows.length===1||!!draftId&&$index===0" @click="remove($index)">删除</el-button></template></el-table-column>
   </el-table>
  </section>
  <el-dialog v-if="active!==null" :model-value="true" :title="dialogTitle+' · 变体 '+(active+1)" width="min(1000px,96vw)" :before-close="closeDetails" :close-on-click-modal="false"><WbListingVariantEditor :key="active+':'+editorMode" ref="details" :mode="editorMode" :shop-id="shop" :shops="shops" :schema="schema" :templates="templates" :draft="{id:active===0?draftId:null,payload:rows[active],shop_id:shop}" @upload-state="uploadingChanged"/><template #footer><el-button type="primary" :disabled="uploading>0" @click="closeDetails">完成编辑</el-button></template></el-dialog>
  <el-drawer v-if="preview" :model-value="true" title="WB 商品预览与发布" size="min(1000px,95vw)" @close="preview=false">
   <template v-if="publication.job"><el-alert :title="wbPublishStatus(publication.job.status)+'：'+publication.job.message" :type="publication.job.status==='completed'?'success':'info'" :closable="false"/><p>任务编号：{{publication.job.id}}</p><section v-for="(item,index) in publication.job.state?.items||[]" :key="item.vendor_code"><p>{{item.vendor_code}} · {{wbPublishPhase(item.phase)}} · {{item.nm_id?'WB '+item.nm_id:'等待商品编号'}}</p><WbPublishMediaSummary :row="publication.job.payload.variants?.[index]||publication.job.payload" :phase="item.phase"/></section><el-button @click="router.push({path:'/listing-publish-records',query:{platform:'wb'}})">查看上架记录</el-button></template>
   <template v-else><el-alert :title="publication.review?'请核对以下已保存的商品资料；确认后会向 WB 创建商品并提交媒体和价格，不推送库存。':'仅预览校验，尚未提交 WB'" :closable="false"/>
    <p v-if="publication.review">目标店铺：{{publication.review.shop_name}} · 币种：{{publication.review.currency}}</p>
    <section v-for="(row,index) in publication.review?publication.review.variants:rows" :key="index"><h3>{{index+1}}. {{row.title||row.card?.title||'待填写标题'}}</h3><p>{{row.vendor_code||row.card?.vendorCode}} · {{(row.sizes||row.card?.sizes||[]).map(size=>'¥ '+(size.price??'待填写')).join(' / ')}} CNY</p><p v-for="(size,sizeIndex) in row.sizes||row.card?.sizes||[]" :key="sizeIndex">{{size.techSize||'无尺码'}} · 条码 {{(size.skus||[]).join(' / ')||'待填写'}}</p><el-image v-for="(image,i) in row.images" :key="image" :src="image" :preview-src-list="row.images" :initial-index="i" preview-teleported fit="cover" class="preview-image"/><video v-if="row.video_url" :src="row.video_url" controls class="preview-video"/></section>
    <el-alert v-for="error in errors" :key="error" :title="error" type="warning" :closable="false"/>
    <div v-if="rows.some(row=>row.card.sizes.some(size=>!size.skus?.length))" class="media-cell-actions"><el-button type="primary" :loading="busy" :disabled="uploading>0||!shop" @click="generateBarcodes()">生成缺失条码</el-button><span>生成后请重新核对并提交。</span></div>
    <el-button v-if="!publication.review&&errors.length===0" :loading="busy" @click="reviewSubmission">重新核对发布资料</el-button>
    <el-button v-if="publication.review?.ok" type="danger" :loading="busy" @click="confirmSubmission">确认提交 WB</el-button><el-button v-else type="primary" :loading="busy" @click="saveOnly">保存草稿</el-button>
   </template>
  </el-drawer>
 </div>
</template>
